/**
 * Service for streaming subscriptions over chain data.
 *
 * Unlike the request/response RPCQueryService and the paginated QueryService,
 * StreamService opens a long-lived server stream that pushes one message per new
 * item as the chain advances. A provider feeds it from whatever head source it
 * has (a state poller, a gap-free chain view, …); the wire contract is the same
 * everywhere.
 *
 * Status codes that end a stream:
 *   OUT_OF_RANGE  the server cannot continue from the resume position (too
 *                 old, or a block it cannot place); backfill with unary
 *                 calls, then reopen.
 *   UNAVAILABLE   the server stopped making progress, or the client read too
 *                 slowly; reopen with a resume position.
 */
export type StreamServiceService = typeof StreamServiceService;
export const StreamServiceService = {
  /**
   * Stream block headers as the chain head advances: one header message per
   * canonical block, ascending, with no number skipped, until the client
   * cancels the stream. After a reorg the server restarts at the fork point: it
   * resends from the first block of the new branch. Client rule: a header whose
   * number is at or below the last one received replaces that number and every
   * number above it. Each header carries hash and parentHash, so a client can
   * check linkage itself.
   */
  streamBlocks: {
    path: "/bds.evm.StreamService/StreamBlocks" as const,
    requestStream: false as const,
    responseStream: true as const,
    requestSerialize: (value: StreamBlocksRequest): Buffer => Buffer.from(StreamBlocksRequest.encode(value).finish()),
    requestDeserialize: (value: Buffer): StreamBlocksRequest => StreamBlocksRequest.decode(value),
    responseSerialize: (value: StreamBlocksResponse): Buffer =>
      Buffer.from(StreamBlocksResponse.encode(value).finish()),
    responseDeserialize: (value: Buffer): StreamBlocksResponse => StreamBlocksResponse.decode(value),
  },
  /**
   * Stream the logs matching a filter, one block at a time, ascending. A
   * block's logs arrive in one or more BlockLogs messages; the last sets
   * complete. A reorg sends Undo with the fork point, then the new branch
   * from the fork point + 1 (REORG_UNDO).
   */
  streamLogs: {
    path: "/bds.evm.StreamService/StreamLogs" as const,
    requestStream: false as const,
    responseStream: true as const,
    requestSerialize: (value: StreamLogsRequest): Buffer => Buffer.from(StreamLogsRequest.encode(value).finish()),
    requestDeserialize: (value: Buffer): StreamLogsRequest => StreamLogsRequest.decode(value),
    responseSerialize: (value: StreamLogsResponse): Buffer => Buffer.from(StreamLogsResponse.encode(value).finish()),
    responseDeserialize: (value: Buffer): StreamLogsResponse => StreamLogsResponse.decode(value),
  },
  /** Stream transactions as they enter the provider's mempool view. */
  streamPendingTransactions: {
    path: "/bds.evm.StreamService/StreamPendingTransactions" as const,
    requestStream: false as const,
    responseStream: true as const,
    requestSerialize: (value: StreamPendingTransactionsRequest): Buffer =>
      Buffer.from(StreamPendingTransactionsRequest.encode(value).finish()),
    requestDeserialize: (value: Buffer): StreamPendingTransactionsRequest =>
      StreamPendingTransactionsRequest.decode(value),
    responseSerialize: (value: StreamPendingTransactionsResponse): Buffer =>
      Buffer.from(StreamPendingTransactionsResponse.encode(value).finish()),
    responseDeserialize: (value: Buffer): StreamPendingTransactionsResponse =>
      StreamPendingTransactionsResponse.decode(value),
  },
} as const;

